export const TooltipNavigationRules = new Map([
	[
		InputNavigationAction.UP,
		(context: FocusContextProvider) => {
			const firstFocusable = context.children()[0];
			context.focusChild(firstFocusable);
		},
	],
	[InputNavigationAction.LEFT, (context: FocusContextProvider) => context.focusPrevious()],
	[InputNavigationAction.RIGHT, (context: FocusContextProvider) => context.focusNext()],
	[InputNavigationAction.NONE, (context: FocusContextProvider) => context.focusCurrent()],
]) as FocusNavigationRulesMap;

export enum TooltipVerticalPosition {
	/** Automatically determine best fit based on position of target  */
	AUTO = "auto",
	/** Bottom of tooltip aligns with top of target */
	TOP = "top",
	/** Center of tooltip aligns with center of target */
	CENTER = "center",
	/** Top of tooltip aligns with bottom of target */
	BOTTOM = "bottom",
}

export enum TooltipHorizontalPosition {
	/** Automatically determine best fit based onposition of target */
	AUTO = "auto",
	/** Right of tooltip aligns with right of target */
	LEFT_COVER = "left_cover",
	/** Right of tooltip aligns with left of target */
	LEFT = "left",
	/** Center of tooltip aligns with center of target */
	CENTER = "center",
	/** Left of tooltip aligns with left of target */
	RIGHT_COVER = "right_cover",
	/** Left of tooltip aligns with right of target */
	RIGHT = "right",
}

export interface TooltipBaseProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/** The vertical position of the tooltip. @default TooltipVerticalPosition.AUTO */
	initialVPosition?: TooltipVerticalPosition;
	/** The horizontal position of the tooltip. @default TooltipVerticalPosition.AUTO */
	initialHPosition?: TooltipHorizontalPosition;
	/** The offset of the tooltip from its trigger. @default 0 */
	offset?: number;
	/** Whether the tooltip is allowed to flip to avoid overflow. @default false */
	allowFlip?: boolean;
	/** Whether the tooltip should show its filigree decorations. @default true */
	showFiligrees?: boolean;
}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface TooltipContentProps extends JSX.HTMLAttributes<HTMLDivElement> {}

function inPx(value: number | undefined) {
	return value === undefined ? undefined : `${value}px`;
}

// Walk up the ancestor chain checking whether the target has been clipped
// out of view by the viewport or any scrolling/clipping ancestor. We don't
// want to keep tracking a target that the player can no longer see.
const isTargetClipped = (el: HTMLElement): boolean => {
	const rect = el.getBoundingClientRect();
	if (rect.bottom <= 0 || rect.top >= window.innerHeight || rect.right <= 0 || rect.left >= window.innerWidth) {
		return true;
	}
	for (let parent = el.parentElement; parent; parent = parent.parentElement) {
		const style = getComputedStyle(parent);
		const clips = style.overflow !== "visible" || style.overflowX !== "visible" || style.overflowY !== "visible";
		if (!clips) {
			continue;
		}
		const clip = parent.getBoundingClientRect();
		if (rect.bottom <= clip.top || rect.top >= clip.bottom || rect.right <= clip.left || rect.left >= clip.right) {
			return true;
		}
	}
	return false;
};

interface TooltipContextData {
	name: string;
	offset: Accessor<number>;
	allowFlip: Accessor<boolean>;
	showFiligrees: Accessor<boolean>;

	initialVPosition: TooltipVerticalPosition | undefined;
	initialHPosition: TooltipHorizontalPosition | undefined;

	/** The vertical position of the tooltip. @default TooltipVerticalPosition.AUTO */
	vPosition: Accessor<TooltipVerticalPosition | undefined>;
	setVPosition: Setter<TooltipVerticalPosition | undefined>;

	/** The horizontal position of the tooltip. @default TooltipVerticalPosition.AUTO */
	hPosition: Accessor<TooltipHorizontalPosition | undefined>;
	setHPosition: Setter<TooltipHorizontalPosition | undefined>;

	triggerContext: Accessor<TriggerActivationContextProvider | undefined>;
	setTriggerContext: Setter<TriggerActivationContextProvider | undefined>;

	childTooltipList: Accessor<string[]>;
	setChildTooltipList: Setter<string[]>;
}

export const TooltipContext = createContext<TooltipContextData>();

// Utility: flip helpers
function flipVertical(pos: TooltipVerticalPosition): TooltipVerticalPosition {
	switch (pos) {
		case TooltipVerticalPosition.TOP:
			return TooltipVerticalPosition.BOTTOM;
		case TooltipVerticalPosition.BOTTOM:
			return TooltipVerticalPosition.TOP;
		default:
			return pos; // CENTER or AUTO (AUTO should already be resolved before flip)
	}
}

function flipHorizontal(pos: TooltipHorizontalPosition): TooltipHorizontalPosition {
	switch (pos) {
		case TooltipHorizontalPosition.LEFT:
			return TooltipHorizontalPosition.RIGHT;
		case TooltipHorizontalPosition.RIGHT:
			return TooltipHorizontalPosition.LEFT;
		case TooltipHorizontalPosition.LEFT_COVER:
			return TooltipHorizontalPosition.RIGHT_COVER;
		case TooltipHorizontalPosition.RIGHT_COVER:
			return TooltipHorizontalPosition.LEFT_COVER;
		default:
			return pos; // CENTER or AUTO (AUTO should already be resolved before flip)
	}
}

interface ComputedTooltipPosition {
	top: number;
	left: number;
	appliedVPos: TooltipVerticalPosition;
	appliedHPos: TooltipHorizontalPosition;
	// Boundary checks before clamping
	overflow: {
		above: boolean;
		below: boolean;
		left: boolean;
		right: boolean;
	};
}

function getTooltipEnterClass(vPosition: TooltipVerticalPosition, hPosition: TooltipHorizontalPosition): string {
	const vertical =
		vPosition === TooltipVerticalPosition.TOP
			? "top"
			: vPosition === TooltipVerticalPosition.BOTTOM
				? "bottom"
				: "center";

	const horizontal =
		hPosition === TooltipHorizontalPosition.LEFT || hPosition === TooltipHorizontalPosition.LEFT_COVER
			? "left"
			: hPosition === TooltipHorizontalPosition.RIGHT || hPosition === TooltipHorizontalPosition.RIGHT_COVER
				? "right"
				: "center";

	return `ui-next-tooltip-enter--${vertical}-${horizontal}`;
}

/** A simple rect used for tooltip positioning */
interface TargetRect {
	x: number;
	y: number;
	width: number;
	height: number;
	top: number;
	left: number;
	right: number;
	bottom: number;
}

/**
 * Compute a tooltip position without clamping and resolve AUTO placements.
 * Returns raw coordinates and overflow flags; caller can decide to flip then clamp.
 */
function computeTooltipPosition(
	targetRect: TargetRect,
	tooltip: HTMLElement,
	desiredV: TooltipVerticalPosition,
	desiredH: TooltipHorizontalPosition,
	offset: number,
): ComputedTooltipPosition {
	const tooltipWidth = tooltip.offsetWidth;
	const tooltipHeight = tooltip.offsetHeight;
	const screenHeight = window.innerHeight;
	const screenWidth = window.innerWidth;

	const targetCenterX = targetRect.x + targetRect.width / 2;
	const targetCenterY = targetRect.y + targetRect.height / 2;
	const tooltipLocalCenterX = tooltipWidth / 2;

	let calcVPos = desiredV;
	let calcHPos = desiredH;

	// Resolve AUTO vertical
	if (calcVPos === TooltipVerticalPosition.AUTO) {
		calcVPos = targetCenterY <= screenHeight / 2 ? TooltipVerticalPosition.BOTTOM : TooltipVerticalPosition.TOP;
	}

	// Resolve AUTO horizontal
	if (calcHPos === TooltipHorizontalPosition.AUTO) {
		const thirdWidth = screenWidth / 3;
		if (targetCenterX < thirdWidth) {
			calcHPos =
				calcVPos === TooltipVerticalPosition.CENTER
					? TooltipHorizontalPosition.RIGHT
					: TooltipHorizontalPosition.RIGHT_COVER;
		} else if (targetCenterX < thirdWidth * 2) {
			if (calcVPos === TooltipVerticalPosition.CENTER) {
				calcHPos =
					targetCenterY > screenWidth / 2 ? TooltipHorizontalPosition.RIGHT : TooltipHorizontalPosition.LEFT;
			} else {
				calcHPos = TooltipHorizontalPosition.CENTER;
			}
		} else {
			calcHPos =
				calcVPos === TooltipVerticalPosition.CENTER
					? TooltipHorizontalPosition.LEFT
					: TooltipHorizontalPosition.LEFT_COVER;
		}
	}

	let top = 0;
	let left = 0;

	switch (calcVPos) {
		case TooltipVerticalPosition.TOP:
			top = targetRect.top - tooltipHeight - offset;
			break;
		case TooltipVerticalPosition.BOTTOM:
			top = targetRect.bottom + offset;
			break;
		case TooltipVerticalPosition.CENTER:
			top = targetCenterY - tooltipHeight / 2;
			break;
		default:
			calcVPos satisfies never;
	}

	switch (calcHPos) {
		case TooltipHorizontalPosition.CENTER:
			left = targetCenterX - tooltipLocalCenterX;
			break;
		case TooltipHorizontalPosition.LEFT_COVER:
			left = targetRect.right - tooltipWidth - offset;
			break;
		case TooltipHorizontalPosition.LEFT:
			left = targetRect.left - tooltipWidth - offset;
			break;
		case TooltipHorizontalPosition.RIGHT:
			left = targetRect.right + offset;
			break;
		case TooltipHorizontalPosition.RIGHT_COVER:
			left = targetRect.left + offset;
			break;
		default:
			calcHPos satisfies never;
	}

	const safeAreaMargins: SafeAreaMargins = UI.getSafeAreaMargins();
	const overflow = {
		above: top < safeAreaMargins.top,
		below: top + tooltipHeight > screenHeight - safeAreaMargins.bottom,
		left: left < safeAreaMargins.left,
		right: left + tooltipWidth > screenWidth - safeAreaMargins.right,
	};

	return { top, left, appliedVPos: calcVPos, appliedHPos: calcHPos, overflow };
}

let curTooltip = 0;

const TooltipRootComponent: ParentComponent<TooltipBaseProps> = (props) => {
	const parentCtx = useContext(TooltipContext);
	const nestedCtx = useContext(NestedTooltipContext);

	const tooltipModel = TooltipModel.get();

	const name = `tooltip-${curTooltip++}`;
	const [triggerContext, setTriggerContext] = createSignal<TriggerActivationContextProvider | undefined>(undefined);
	const [vPosition, setVPosition] = createSignal<TooltipVerticalPosition | undefined>(props.initialVPosition);
	const [hPosition, setHPosition] = createSignal<TooltipHorizontalPosition | undefined>(props.initialHPosition);
	const [childTooltipList, setChildTooltipList] = createArraySignal<string>([]);
	const offset = createMemo(() => props.offset ?? 0);

	if (!isNestedTooltipContextDisabled(nestedCtx)) {
		onMount(() => {
			parentCtx?.setChildTooltipList((tooltips) => {
				tooltips.push(name);
				return tooltips;
			});
			onCleanup(() => {
				parentCtx?.setChildTooltipList((tooltips) => {
					const index = tooltips.indexOf(name);
					if (index !== -1) {
						tooltips.splice(index, 1);
					}
					return tooltips;
				});
			});
		});
	}

	onMount(() => {
		const unregister = tooltipModel.register(name, childTooltipList);
		onCleanup(() => {
			unregister();
		});
	});

	return (
		<TooltipContext.Provider
			value={{
				name,
				initialVPosition: props.initialVPosition,
				initialHPosition: props.initialHPosition,
				offset,
				allowFlip: () => props.allowFlip ?? false,
				showFiligrees: () => props.showFiligrees ?? true,
				vPosition,
				setVPosition,
				hPosition,
				setHPosition,
				triggerContext,
				setTriggerContext,
				childTooltipList,
				setChildTooltipList,
			}}
		>
			{props.children}
		</TooltipContext.Provider>
	);
};

const onMouseMove = (e: MouseEvent) => {
	setMousePosition({ x: e.clientX, y: e.clientY });
};
document.addEventListener("mousemove", onMouseMove, { capture: true });

const [mousePosition, setMousePosition] = createSignal({ x: 0, y: 0 });
const tooltipRoot = document.getElementById("uinext-tooltips") ?? document.body;
interface TooltipContentInternalProps {
	root: Accessor<HTMLDivElement | undefined>;
	focusCtx: Accessor<FocusContextProvider | null>;
	setFocusCtx: Setter<FocusContextProvider | null>;
	enterAnimationClass: Accessor<string>;
}

const TooltipContentInternal: ParentComponent<TooltipContentInternalProps> = (props) => {
	onMount(() => {
		const focusCtx = useFocusContext()!;
		// register the root so we can shift focus to a non-keyword element which allows controllers to navigate to the previous tooltip
		focusCtx.register(props.root());
		props.setFocusCtx(focusCtx);
	});

	onCleanup(() => {
		props.focusCtx()?.unregister(props.root());
		props.setFocusCtx(null);
	});

	return <div class={`ui-next-tooltip-enter ${props.enterAnimationClass()}`}>{props.children}</div>;
};

interface TooltipActiveContentProps {
	contentProps: ParentProps<TooltipContentProps>;
	shouldActivate: Accessor<boolean>;
}

const TooltipActiveContentComponent = (props: TooltipActiveContentProps) => {
	const ctx = useContext(TooltipContext);
	if (!ctx) {
		throw new Error("TooltipActiveContentComponent must be used within a TooltipContext");
	}

	const shouldActivate = () => props.shouldActivate();
	const tooltipModel = TooltipModel.get();
	const focusManager = FocusManager.get();
	const [root, setRoot] = createPropsRefSignal<HTMLDivElement>(() => props.contentProps.ref);
	const parentNestedCtx = useContext(NestedTooltipContext);

	// Hard limit nested tooltips at MAX_VISIBLE_TOOLTIPS to avoid OOM issues.
	const nestedTooltipsDisabled = createMemo(() => {
		if (isNestedTooltipContextDisabled(parentNestedCtx)) {
			return true;
		}
		const active = tooltipModel.active();
		return active.length >= MAX_VISIBLE_TOOLTIPS && active[active.length - 1] === ctx.name;
	});

	const [top, setTop] = createSignal<number | undefined>();
	const [left, setLeft] = createSignal<number | undefined>();
	const [scale, setScale] = createSignal(1);
	const [isCalculatingPosition, setIsCalculatingPosition] = createSignal(true);
	const [didCalculatePosition, setDidCalculatePosition] = createSignal(false);
	const [isAnimating, setIsAnimating] = createSignal(false);
	const [isClipped, setIsClipped] = createSignal(false);

	const isLayoutComplete = createLayoutComplete();

	const target = createMemo(() => tooltipModel.getTarget(ctx.name));
	const [targetRect, setTargetRect] = createSignal<TargetRect | undefined>();

	// Locked state used to conditionally render a backdrop overlay that absorbs clicks
	const isTop = createMemo(() => {
		const active = tooltipModel.active();
		return active.length > 0 && active[active.length - 1] === ctx.name;
	});

	createEffect(
		on([() => tooltipModel.isActive(ctx.name), isAnimating], () => {
			setDidCalculatePosition(false);
		}),
	);

	// Determine if we should visibly render this tooltip (toggles display).
	const shouldShow = createMemo(() => targetRect() !== undefined && !isClipped());

	const enterAnimationClass = createMemo(() =>
		getTooltipEnterClass(
			ctx.vPosition() ?? TooltipVerticalPosition.AUTO,
			ctx.hPosition() ?? TooltipHorizontalPosition.AUTO,
		),
	);

	const setTargetRectFromXY = (x: number, y: number) => {
		setTargetRect({
			x,
			y,
			width: 0,
			height: 0,
			top: y,
			right: x,
			bottom: y,
			left: x,
		});
	};

	const onCameraChanged = (_state: CameraState) => {
		const currentTarget = target();
		if (currentTarget && !(currentTarget instanceof HTMLElement) && !tooltipModel.isLocked(ctx.name)) {
			const screenUV = WorldUI.getScreenPlotPos(currentTarget);
			if (screenUV) {
				const x = screenUV.x * window.innerWidth;
				const y = screenUV.y * window.innerHeight;
				setTargetRectFromXY(x, y);
			} else {
				// plot is not currently on screen
				setTargetRect(undefined);
			}
		}
	};
	const isKBM = createMemo(() => IsKeyboardActive() || IsMouseActive());

	createEffect(() => {
		if (isTop()) {
			engine.on("CameraChanged", onCameraChanged);
			onCleanup(() => {
				engine.off("CameraChanged", onCameraChanged);
			});
		}
	});

	createEffect(
		on(
			[target, () => tooltipModel.isLocked(ctx.name), mousePosition],
			([currentTarget, isLocked, currentMousePosition]) => {
				if (currentTarget && !(currentTarget instanceof HTMLElement) && isTop() && !isLocked) {
					// When using a keyboard + mouse, we want to position based on the mouse cursor
					// however, the player will need to use the keyboard to trigger the locking of the tooltip
					// so we need to check for keyboard or mouse input
					if (isKBM()) {
						// check if mouse position still points to the same plot

						const hoveredPlot = Camera.pickPlotFromPoint(currentMousePosition.x, currentMousePosition.y);
						if (hoveredPlot?.x === currentTarget.x && hoveredPlot?.y === currentTarget.y) {
							setTargetRectFromXY(currentMousePosition.x, currentMousePosition.y);
						} else {
							// mouse has moved off the target plot, this can happen when UI is removed from underneath the mouse cursor and the player hasn't moved the mouse yet
							setTargetRect(undefined);
						}
					} else {
						const screenUV = WorldUI.getScreenPlotPos(currentTarget);
						if (screenUV) {
							const x = screenUV.x * window.innerWidth;
							const y = screenUV.y * window.innerHeight;
							setTargetRectFromXY(x, y);
						} else {
							// plot is not currently on screen
							setTargetRect(undefined);
						}
					}
				} else {
					if (currentTarget instanceof HTMLElement) {
						setTargetRect(currentTarget.getBoundingClientRect());
					}
				}
			},
		),
	);

	// Animation/size tracking
	createEffect(() => {
		const currentRoot = root();
		const currentTarget = target();
		if (!(currentTarget instanceof HTMLElement) || !currentRoot || !isTop() || tooltipModel.isLocked(ctx.name)) {
			return;
		}

		const updateTargetRect = () => {
			setTargetRect(currentTarget.getBoundingClientRect());
		};

		let animationCount = 0;
		const onAnimationStart = (e: AnimationEvent | TransitionEvent) => {
			// delay positioning updates until the end of the animation
			if (e.target instanceof Element && (e.target === currentTarget || e.target.contains(currentTarget))) {
				// try to determine whether the animation is infinite or not in which case we'll trigger the tooltip anyway
				// we assume they are infinite by default to avoid having tooltips not show
				let isAnimationInfinite = true;
				if (e instanceof AnimationEvent) {
					const anim = e.target.getAnimations().find((a) => {
						if (a instanceof CSSAnimation) {
							return a.animationName === e.animationName;
						}
						return false;
					});

					// Only for web animations api
					if (anim?.effect != null) {
						isAnimationInfinite = anim.effect.getTiming().iterations === Infinity;
					} else {
						// check computed style as a fallback
						const style = getComputedStyle(e.target);
						isAnimationInfinite = style.animationIterationCount === "infinite";
					}
				} else if (e instanceof TransitionEvent) {
					// noop, transitions aren't infinite by nature
				}

				if (!isAnimationInfinite) {
					animationCount++;
					setIsAnimating(true);
				}
			}
		};

		const onAnimationEnd = (e: AnimationEvent | TransitionEvent) => {
			// Only react to animations on the target or one of its ancestors (which
			// move the target); ignore unrelated animations elsewhere in the document.
			if (e.target instanceof Element && (e.target === currentTarget || e.target.contains(currentTarget))) {
				animationCount--;
				if (animationCount === 0) {
					setIsAnimating(false);
				}
				updateTargetRect();
			}
		};

		// Reposition when an ancestor scrolls. Scroll events don't bubble, so we
		// listen in the capture phase and only react when the scrolled node
		// actually contains the target (i.e. the scroll moves the target on screen).
		let scrollRafHandle: number | undefined;
		const onScroll = (e: Event) => {
			if (!(e.target instanceof Element) || !e.target.contains(currentTarget)) {
				return;
			}
			// Coalesce bursts of scroll events into a single rect update per frame.
			if (scrollRafHandle === undefined) {
				scrollRafHandle = requestAnimationFrame(() => {
					scrollRafHandle = undefined;
					setIsClipped(isTargetClipped(currentTarget));
				});
			}
		};

		const observer = new ResizeObserver(updateTargetRect);
		observer.observe(currentTarget);
		observer.observe(currentRoot);
		document.addEventListener("animationstart", onAnimationStart, true);
		document.addEventListener("transitionstart", onAnimationStart, true);
		document.addEventListener("animationend", onAnimationEnd, true);
		document.addEventListener("transitionend", onAnimationEnd, true);
		document.addEventListener("scroll", onScroll, true);

		onCleanup(() => {
			observer.disconnect();
			if (scrollRafHandle !== undefined) {
				cancelAnimationFrame(scrollRafHandle);
			}
			document.removeEventListener("animationstart", onAnimationStart, true);
			document.removeEventListener("transitionstart", onAnimationStart, true);
			document.removeEventListener("animationend", onAnimationEnd, true);
			document.removeEventListener("transitionend", onAnimationEnd, true);
			document.removeEventListener("scroll", onScroll, true);
		});
	});

	createEffect(() => {
		const tooltip = root();
		const currentTargetRect = targetRect();
		if (
			!currentTargetRect ||
			!tooltip ||
			!isLayoutComplete() ||
			!shouldActivate() ||
			// ensure tooltip positions are calculated at least once,
			// mostly to ensure tooltips on touch have their positions calculated because they can start locked
			(tooltipModel.isLocked(ctx.name) && didCalculatePosition())
		) {
			return;
		}

		const offset = ctx.offset ?? 0;
		setIsCalculatingPosition(true);

		// eslint-disable-next-line solid/reactivity
		waitForLayout(() => {
			// Check for active or locked after the wait too, because it could have changed
			if (!shouldActivate()) {
				setIsCalculatingPosition(false);
				return;
			}

			if (tooltipModel.isLocked(ctx.name) && didCalculatePosition()) {
				// console.log(`Tooltip "${ctx.name}" is locked, skipping position update`);
				setIsCalculatingPosition(false);
				return;
			}

			// Initial raw computation
			const initial = computeTooltipPosition(
				currentTargetRect,
				tooltip,
				ctx.initialVPosition ?? ctx.vPosition() ?? TooltipVerticalPosition.AUTO,
				ctx.initialHPosition ?? ctx.hPosition() ?? TooltipHorizontalPosition.AUTO,
				offset(),
			);

			let final = initial;

			if (ctx.allowFlip()) {
				// Decide flips if overflowing (before clamping)
				const needFlipVertical = initial.overflow.above || initial.overflow.below;
				const needFlipHorizontal = initial.overflow.left || initial.overflow.right;

				if (needFlipVertical || needFlipHorizontal) {
					const flippedVPos = flipVertical(initial.appliedVPos);
					const flippedHPos = flipHorizontal(initial.appliedHPos);
					ctx.setVPosition(flippedVPos);
					ctx.setHPosition(flippedHPos);
					final = computeTooltipPosition(currentTargetRect, tooltip, flippedVPos, flippedHPos, offset());
				}
			}

			// Clamp after potential flip
			const safeAreaMargins: SafeAreaMargins = UI.getSafeAreaMargins();

			const tooltipWidth = tooltip.offsetWidth;
			const tooltipHeight = tooltip.offsetHeight;
			const screenHeight = window.innerHeight;
			const screenWidth = window.innerWidth;

			const scaleValue = Math.min(1, screenWidth / tooltipWidth, screenHeight / tooltipHeight);

			const xOffset = ((1 - scaleValue) * tooltipWidth) / 2;
			const yOffset = ((1 - scaleValue) * tooltipHeight) / 2;

			const scaledWidth = tooltipWidth * scaleValue;
			const scaledHeight = tooltipHeight * scaleValue;

			// Determine ideal visual position (before clamping) based on alignment
			let idealVisualLeft = final.left;
			if (
				final.appliedHPos === TooltipHorizontalPosition.LEFT ||
				final.appliedHPos === TooltipHorizontalPosition.LEFT_COVER
			) {
				idealVisualLeft += 2 * xOffset;
			} else if (final.appliedHPos === TooltipHorizontalPosition.CENTER) {
				idealVisualLeft += xOffset;
			}

			let idealVisualTop = final.top;
			if (final.appliedVPos === TooltipVerticalPosition.TOP) {
				idealVisualTop += 2 * yOffset;
			} else if (final.appliedVPos === TooltipVerticalPosition.CENTER) {
				idealVisualTop += yOffset;
			}

			// Clamp visual position
			const clampedVisualTop = Math.min(
				Math.max(safeAreaMargins.top, idealVisualTop),
				screenHeight - scaledHeight - safeAreaMargins.bottom,
			);
			const clampedVisualLeft = Math.min(
				Math.max(safeAreaMargins.left, idealVisualLeft),
				screenWidth - scaledWidth - safeAreaMargins.right,
			);

			batch(() => {
				// Convert back to CSS position (compensating for transform origin center)
				setTop(clampedVisualTop - yOffset);
				setLeft(clampedVisualLeft - xOffset);
				setScale(scaleValue);

				setIsCalculatingPosition(false);
				setDidCalculatePosition(true);
			});
		});
	});

	createEffect(
		on(
			() => tooltipModel.isLocked(ctx.name),
			(locked) => {
				const currentRoot = root();
				if (locked && currentRoot) {
					FocusManager.get().setFocus(currentRoot);

					onCleanup(() => {
						if (focusManager.currentFocus() === currentRoot) {
							// ideally we'd call clearFocus, but clearFocus doesn't work for elements that aren't connected to the DOM
							focusManager.setFocus(document.body);
						}
					});
				}
			},
		),
	);

	// Tracks the time the most recent inspect button was pressed so we can
	// distinguish a quick press (? lock) from a long hold (? hide, handled by
	// the tooltip model's global listener).
	let inspectStartTime = 0;

	const onEngineInput = (inputEvent: InputEngineEvent) => {
		const { name, status } = inputEvent.detail;
		if (tooltipModel.locked()) {
			inputEvent.preventDefault();
		}
		const isInspectAction = name === "keyboard-inspect-tooltip" || name === "toggle-tooltip";

		if (isInspectAction && status === InputActionStatuses.START) {
			inspectStartTime = performance.now();
			inputEvent.preventDefault();
			return;
		}

		if (status === InputActionStatuses.FINISH) {
			let didHandleEvent = false;
			if (isInspectAction) {
				const holdDuration = performance.now() - inspectStartTime;
				if (holdDuration >= HIDE_TOOLTIPS_HOLD_THRESHOLD_MS) {
					// The hold-to-hide action is handled by the tooltip model; suppress
					// the lock so we don't toggle inspect after a hold.
					didHandleEvent = true;
				} else {
					tooltipModel.lock();
					didHandleEvent = true;
				}
			} else if (inputEvent.isCancelInput() && tooltipModel.locked()) {
				tooltipModel.unlockAll();
				didHandleEvent = true;
			}
			if (didHandleEvent) {
				// we *must* prevent default here to stop context-manager from dispatching the event to us twice.
				inputEvent.preventDefault();
			}
		}
	};

	createEffect(() => {
		if (isTop()) {
			window.addEventListener("engine-input", onEngineInput, true);
			onCleanup(() => {
				window.removeEventListener("engine-input", onEngineInput, true);
			});
		} else {
			window.removeEventListener("engine-input", onEngineInput, true);
		}
	});

	const [focusCtx, setFocusCtx] = createSignal<FocusContextProvider | null>(null);
	const onNavigate = (navigationEvent: NavigateInputEvent) => {
		if (navigationEvent.detail.status != InputActionStatuses.FINISH) {
			return;
		}

		if (focusCtx()?.navigate(navigationEvent.detail.navigation)) {
			navigationEvent.preventDefault();
			navigationEvent.stopPropagation();
		}
	};

	return (
		<Portal mount={tooltipRoot}>
			<>
				{/* Backdrop overlay to block clicks to underlying UI when tooltip is locked */}
				{/* don't use isLocked here because we only want the top-level locked tooltip to have a backdrop*/}
				<Show when={tooltipModel.locked() == ctx.name}>
					<Activatable
						name="TooltipBackdrop"
						onActivate={() => tooltipModel.unlockAll()}
						disableTrigger={true}
						class="fixed inset-0 pointer-events-auto"
						style={{
							"background-color": "rgba(0 0 0 / .5)",
						}}
					/>
				</Show>

				<Slot
					{...props.contentProps}
					name="TooltipContentSlot"
					ref={setRoot}
					disableFocus={!tooltipModel.isLocked(ctx.name)}
					class={`absolute visible tooltip-content-root ${props.contentProps.class ?? ""}`}
					classList={{
						"opacity-0": isCalculatingPosition() && !didCalculatePosition() && !isAnimating(),
						hidden: !shouldShow(),
						"pointer-events-auto": tooltipModel.isLocked(ctx.name) || IsTouchActive(),
						"pointer-events-none": !tooltipModel.isLocked(ctx.name) && !IsTouchActive(),
					}}
					style={{ top: inPx(top()), left: inPx(left()), transform: `scale(${scale()})` }}
					navRules={TooltipNavigationRules}
					lockNavigation
					on:navigate-input={onNavigate}
					on:engine-input={(e: InputEngineEvent) => {
						if (e.detail.status === InputActionStatuses.FINISH && e.detail.name === "touch-tap") {
							e.stopPropagation();

							if (!isTop()) {
								tooltipModel.pop();
							}
						}
					}}
					tabIndex={-1}
				>
					{/* We intentionally create an inner component to get the slot focus context instead of using the slot's 
									setFocusContext prop because the registration order would be different. */}
					<TooltipContentInternal
						root={root}
						focusCtx={focusCtx}
						setFocusCtx={setFocusCtx}
						enterAnimationClass={enterAnimationClass}
					>
						<NestedTooltipContext.Provider value={{ disabled: nestedTooltipsDisabled }}>
							{props.contentProps.children}
						</NestedTooltipContext.Provider>
					</TooltipContentInternal>
				</Slot>
			</>
		</Portal>
	);
};

const TooltipContentComponent: ParentComponent<TooltipContentProps> = (props) => {
	const tooltipModel = TooltipModel.get();
	const ctx = useContext(TooltipContext);

	if (!ctx) {
		throw new Error("Tooltip.Content must be used within a <Tooltip> root component");
	}

	const shouldActivate = () =>
		!tooltipModel.tooltipsHidden() && (tooltipModel.isLocked(ctx.name) || tooltipModel.isActive(ctx.name));

	return (
		// Hidden span prevents empty text nodes being rendered as placeholders in the DOM tree
		<span
			class="hidden"
			data-tooltip-id={ctx.name}
		>
			<Show when={shouldActivate()}>
				<TooltipActiveContentComponent
					contentProps={props}
					shouldActivate={shouldActivate}
				/>
			</Show>
		</span>
	);
};

type TooltipInspectHintProps = JSX.HTMLAttributes<HTMLDivElement> & {
	progressBarRef?: (el: HTMLDivElement | null) => void;
	isLargeContent?: Accessor<boolean>; // When true there is enough content to justify showing the inspect hint even if no nested tooltip links exist.
	handlers?: {
		// if we don't have a context we can use the handlers directly to change state.
		isLocked: Accessor<boolean>;
		isTopLevelActiveAndLocked: Accessor<boolean>;
		tooltipCount: Accessor<number>;
	};
};

const TooltipInspectHintComponent: ParentComponent<TooltipInspectHintProps> = (props) => {
	const tooltipModel = TooltipModel.get();
	const ctx = useContext(TooltipContext);
	const [local, other] = splitProps(props, ["class", "progressBarRef", "isLargeContent", "handlers"]);

	const hotkeyIconProvider: HotkeyIconContextProvider = { disabled: () => false, actionName: () => "toggle-tooltip" };

	// eslint-disable-next-line solid/reactivity -- we only need to check for handlers existence once.
	if (!ctx && local.handlers == undefined) {
		throw new Error(
			"Tooltip.InspectHint must be used within a <Tooltip> root component or managed individually using handlers.",
		);
	}

	const isLocked = () => {
		if (local.handlers) {
			return local.handlers.isLocked();
		}
		if (ctx) {
			return tooltipModel.isLocked(ctx.name);
		}
	};

	const tooltipCount = createMemo<number>(() => {
		if (local.handlers) {
			return local.handlers.tooltipCount();
		}
		if (ctx) {
			return ctx.childTooltipList().length;
		} else {
			console.error("Tooltip.InspectHint The tooltip count should be handled to show the tooltip.");
			return 0;
		}
	});

	const isTopLevelActiveAndLocked = createMemo(() => {
		if (local.handlers) {
			return local.handlers.isTopLevelActiveAndLocked();
		}
		const active = tooltipModel.active();
		if (ctx && active.length > 0) {
			return active[active.length - 1] == ctx.name && isLocked();
		} else {
			return isLocked();
		}
	});

	const shouldShowHoldToHideAction = createMemo(() => {
		if (local.handlers) return false;

		// Don't show the "Hide" action if there are no nested tooltip links and content is small/simple.
		const hasTooltips = tooltipCount() > 0;
		const hasLargeContent = local.isLargeContent ? local.isLargeContent() : false;
		if (!hasTooltips && !hasLargeContent) return false;

		const active = tooltipModel.active();
		return active.length > 0 && active[0] === ctx?.name && !tooltipModel.isLocked(ctx.name);
	});

	const isKBM = createMemo(() => IsKeyboardActive() || IsMouseActive());

	const strClose = Locale.toUpper("LOC_GENERIC_CLOSE");

	const inspectText = () => (
		<L10n.Stylize
			text={isTopLevelActiveAndLocked() ? strClose : "LOC_INSPECT_TOOLTIP"}
			class="text-sm font-body uppercase mr-2"
			classList={{
				"text-accent-1": isLocked(),
			}}
			style={{
				"letter-spacing": "-0.5px",
			}}
			role="heading"
		/>
	);

	const navHelp = (isHoldAction = false) => {
		if (isKBM()) {
			return (
				<KBMNavHelp
					actionName="keyboard-inspect-tooltip"
					isHoldAction={isHoldAction}
					holdTimeMs={HIDE_TOOLTIPS_HOLD_THRESHOLD_MS}
				/>
			);
		} else {
			return (
				<NavHelp
					actionName="toggle-tooltip"
					class="size-8"
					isHoldAction={isHoldAction}
					holdTimeMs={HIDE_TOOLTIPS_HOLD_THRESHOLD_MS}
				/>
			);
		}
	};

	return (
		<Show when={!IsTouchActive() && (tooltipCount() > 0 || local.isLargeContent?.())}>
			<div
				{...other}
				class={`flex flex-col justify-center items-center px-2 gap-1 text-sm text-accent-3 font-body uppercase ${local.class ?? ""}`}
				style={{
					"letter-spacing": "-0.5px",
				}}
			>
				<HotkeyIconContext.Provider value={hotkeyIconProvider}>
					<div class="flex items-center justify-center">
						<Show when={tooltipCount() > 0 && (!isLocked() || isTopLevelActiveAndLocked())}>
							<div
								class="flex flex-row items-center"
								classList={{
									"mr-1": shouldShowHoldToHideAction(),
								}}
							>
								{inspectText()}
								{navHelp()}
							</div>
						</Show>
						<Show when={shouldShowHoldToHideAction()}>
							<span class="flex flex-row items-center">
								<L10n.Compose
									text="LOC_UI_HOLD_INPUT"
									args={["LOC_UI_GENERIC_HIDE"]}
								/>
								&nbsp;
								{navHelp(true)}
							</span>
						</Show>
					</div>
					<Show when={tooltipCount() > 0}>
						<div
							class="relative h-0\.5 w-full flex-auto bg-secondary scale-0 origin-center -mb-2 rounded"
							ref={local.progressBarRef}
						/>
					</Show>
				</HotkeyIconContext.Provider>
			</div>
		</Show>
	);
};

interface TooltipTriggerBodyProps {
	tooltipName: string;
	hostProps: JSX.HTMLAttributes<HTMLDivElement>;
	setRoot: Setter<HTMLElement | undefined>;
	clearTooltipDelay: () => void;
	onShowTooltip: (event: MouseEvent | FocusEvent) => void;
	onMouseLeave: (event: MouseEvent) => void;
	onBlur: (event: FocusEvent) => void;
	onShowTooltipTouch: (event: InputEngineEvent) => void;
}

const TooltipTriggerInternal: ParentComponent<TooltipTriggerBodyProps> = (props) => {
	const [needsWrapper, setNeedsWrapper] = createSignal(false);
	const resolved = children(() => props.children);

	createEffect(
		on(resolved, (resolvedChildren) => {
			let element: HTMLElement | undefined;

			if (resolvedChildren) {
				if (!Array.isArray(resolvedChildren) && resolvedChildren instanceof HTMLElement) {
					element = resolvedChildren;
				} else if (
					Array.isArray(resolvedChildren) &&
					resolvedChildren.length === 1 &&
					resolvedChildren[0] instanceof HTMLElement
				) {
					element = resolvedChildren[0];
				}
			}

			if (element) {
				// Attach event handlers directly to the element
				element.addEventListener("mouseover", props.onShowTooltip);
				element.addEventListener("mouseleave", props.onMouseLeave);
				element.addEventListener("focus", props.onShowTooltip);
				element.addEventListener("blur", props.onBlur);
				element.addEventListener("engine-input", props.onShowTooltipTouch);

				onCleanup(() => {
					props.clearTooltipDelay();
					element.removeEventListener("mouseover", props.onShowTooltip);
					element.removeEventListener("mouseleave", props.onMouseLeave);
					element.removeEventListener("focus", props.onShowTooltip);
					element.removeEventListener("blur", props.onBlur);
					element.removeEventListener("engine-input", props.onShowTooltipTouch);
				});

				props.setRoot(element);
				setNeedsWrapper(false);
			} else {
				// Need to wrap in a div
				props.clearTooltipDelay();
				setNeedsWrapper(true);
			}
		}),
	);

	return (
		<Show
			when={!needsWrapper()}
			fallback={
				<div
					{...props.hostProps}
					on:mouseover={props.onShowTooltip}
					on:mouseleave={props.onMouseLeave}
					on:focus={props.onShowTooltip}
					on:blur={props.onBlur}
					on:engine-input={props.onShowTooltipTouch}
					ref={props.setRoot}
					use:isFocusable={[true, undefined]}
					data-tooltip-id={props.tooltipName}
				>
					{resolved()}
				</div>
			}
		>
			{resolved()}
		</Show>
	);
};

const TooltipTriggerComponent: ParentComponent<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	const tooltipCtx = useContext(TooltipContext);
	if (!tooltipCtx) {
		throw new Error("Tooltip.Trigger must be used within a <Tooltip> root component");
	}
	const parentContext = useContext(TriggerActivationContext);
	const tooltipModel = TooltipModel.get();
	// const parentTriggerContext = useContext(TriggerActivationContext);
	const triggerContext = new TriggerActivationContextProvider(tooltipModel, parentContext, () => tooltipCtx.name);
	tooltipCtx.setTriggerContext(triggerContext);
	const [root, setRoot] = createSignal<HTMLElement | undefined>();
	let tooltipDelayHandle: number | undefined;

	const clearTooltipDelay = () => {
		if (tooltipDelayHandle !== undefined) {
			clearTimeout(tooltipDelayHandle);
			tooltipDelayHandle = undefined;
		}
	};

	const triggerTooltipWithDelay = () => {
		clearTooltipDelay();
		const activeTooltips = tooltipModel.active();
		const delay = activeTooltips.length === 0 ? Configuration.getUser().tooltipDelay : 0;
		const triggerRoot = root();
		if (delay <= 0) {
			tooltipModel.triggerTooltip(tooltipCtx.name, TriggerType.Focus, triggerRoot);
			return;
		}

		tooltipDelayHandle = window.setTimeout(() => {
			tooltipDelayHandle = undefined;
			tooltipModel.triggerTooltip(tooltipCtx.name, TriggerType.Focus, triggerRoot);
		}, delay);
	};

	const onShowTooltip = (event: MouseEvent | FocusEvent) => {
		if (event instanceof MouseEvent && event.screenX === 0 && event.screenY === 0) {
			return;
		}

		// This stopPropagation is necessary to allow components which have a tooltip which also has other content with tooltips (not nested tooltips)
		event.stopPropagation();

		triggerTooltipWithDelay();
	};

	const onShowTooltipTouch = (event: InputEngineEvent) => {
		if (event.detail.status !== InputActionStatuses.FINISH) {
			return;
		}

		if (event.detail.name !== "touch-press") {
			return;
		}

		const activeTooltips = tooltipModel.active();
		const isActive = activeTooltips[activeTooltips.length - 1] === tooltipCtx.name;
		if (isActive) {
			tooltipModel.pop();
		} else {
			// on touch, the user may inspect nested tooltips of active but unlocked tooltips
			// so just confirm that the active tooltip is our parent context
			if (activeTooltips.length > 0 && activeTooltips[activeTooltips.length - 1] !== parentContext?.name()) {
				// The current tooltip being shown is a sibling tooltip which is not yet locked, pop it before showing ours
				if (
					tooltipModel.locked() !== activeTooltips[activeTooltips.length - 1] &&
					activeTooltips[activeTooltips.length - 2] === parentContext?.name()
				) {
					tooltipModel.pop();
				} else {
					// active tooltip is not our parent, nor a child of our parent, do not trigger.
					return;
				}
			}

			triggerTooltipWithDelay();
		}

		event.stopPropagation();
		event.preventDefault();
	};

	const onMouseLeave = (_event: MouseEvent) => {
		clearTooltipDelay();
		tooltipModel.triggerTooltip(tooltipCtx.name, TriggerType.Blur, root());
	};

	const onBlur = (event: FocusEvent) => {
		event.stopPropagation();
		clearTooltipDelay();
		tooltipModel.triggerTooltip(tooltipCtx.name, TriggerType.Blur, root());
	};

	onCleanup(() => {
		clearTooltipDelay();
	});

	return (
		<TriggerActivationContext.Provider value={triggerContext}>
			<TooltipTriggerInternal
				tooltipName={tooltipCtx.name}
				hostProps={props}
				setRoot={setRoot}
				clearTooltipDelay={clearTooltipDelay}
				onShowTooltip={onShowTooltip}
				onMouseLeave={onMouseLeave}
				onBlur={onBlur}
				onShowTooltipTouch={onShowTooltipTouch}
			>
				{props.children}
			</TooltipTriggerInternal>
		</TriggerActivationContext.Provider>
	);
};

const AUTOLOCK_PROGRESS_ANIMATION_NAME = "tooltip-autolock-progress";
const AUTOLOCK_FRAME_ANIMATION_NAME = "tooltip-autolock-frame";

// The frame glow is a fixed-duration animation (9 frames at 30fps = 300ms)
// that peaks at the lock point. It starts playing before the lock so the
// fade-in (5/9 of the duration) aligns with the end of the progress bar.
const AUTOLOCK_FRAME_GLOW_DURATION_MS = 300;
const AUTOLOCK_FRAME_GLOW_LEAD_MS = (5 / 9) * AUTOLOCK_FRAME_GLOW_DURATION_MS;

interface TooltipFrameProps extends JSX.HTMLAttributes<HTMLDivElement> {
	hideHint?: boolean;
}
const TooltipFrameComponent: ParentComponent<TooltipFrameProps> = (props) => {
	const ctx = useContext(TooltipContext);
	const tooltipModel = TooltipModel.get();
	const [local, other] = splitProps(props, ["hideHint", "class", "children"]);
	const [frameRef, setFrameRef] = createSignal<HTMLDivElement | undefined>(undefined);
	const [progressBarRef, setProgressBarRef] = createSignal<HTMLDivElement | undefined>(undefined);
	const [contentRef, setContentRef] = createSignal<HTMLDivElement | undefined>(undefined);
	const [isLargeContent, setIsLargeContent] = createSignal(false);
	let frameGlowTimeout: number | undefined;

	const isAutoLocking = createMemo(() => (ctx ? tooltipModel.isAutoLocking(ctx.name) : false));

	const startAutoLockAnimation = (element: HTMLDivElement, animationClass: string, durationMs: number) => {
		element.style.animationDuration = `${durationMs}ms`;
		element.classList.remove(animationClass);
		element.classList.add(animationClass);
	};

	const stopAutoLockAnimation = (element: HTMLDivElement | undefined, animationClass: string) => {
		if (!element) {
			return;
		}

		element.classList.remove(animationClass);
		element.style.animationDuration = "";
	};

	const stopAllAnimations = () => {
		stopAutoLockAnimation(progressBarRef(), AUTOLOCK_PROGRESS_ANIMATION_NAME);
		stopAutoLockAnimation(frameRef(), AUTOLOCK_FRAME_ANIMATION_NAME);
		if (frameGlowTimeout !== undefined) {
			clearTimeout(frameGlowTimeout);
			frameGlowTimeout = undefined;
		}
	};

	// Measure the content height to determine if we should show the inspect hint.
	const threshholdContentHeight = 200; // Should roughly allow 2 lines of (large) text with a border before kicking in.
	createEffect(() => {
		const contentEl = contentRef();
		if (!contentEl) return;
		const observer = new ResizeObserver((entries) => {
			for (const entry of entries) {
				setIsLargeContent(entry.contentRect.height > threshholdContentHeight);
			}
		});

		observer.observe(contentEl);
		onCleanup(() => observer.disconnect());
	});

	createEffect(
		on([isAutoLocking, progressBarRef, frameRef], ([autoLocking, progressBarRef, frameRef]) => {
			const autolockMs = Configuration.getUser().tooltipAutolock;
			if (autolockMs <= 100 || !progressBarRef || !frameRef) {
				// don't animate less than 100ms
				stopAllAnimations();
				return;
			}

			if (autoLocking) {
				// Progress bar fills over the full autolock duration
				startAutoLockAnimation(progressBarRef, AUTOLOCK_PROGRESS_ANIMATION_NAME, autolockMs);

				// Frame glow is a fixed-duration animation that peaks at the lock point.
				// Delay its start so the fade-in portion ends when the lock fires.
				const glowDelayMs = Math.max(0, autolockMs - AUTOLOCK_FRAME_GLOW_LEAD_MS);
				frameGlowTimeout = window.setTimeout(() => {
					startAutoLockAnimation(frameRef, AUTOLOCK_FRAME_ANIMATION_NAME, AUTOLOCK_FRAME_GLOW_DURATION_MS);
					frameGlowTimeout = undefined;
				}, glowDelayMs);
			} else {
				stopAllAnimations();
			}
		}),
	);

	return (
		<div
			{...other}
			class={`img-tooltip-border img-tooltip-bg p-4 ${local.class ?? ""}`}
			classList={{ "min-w-48": !local.hideHint }}
			ref={setFrameRef}
		>
			<Show when={!IsMouseActive() && !IsKeyboardActive()}>
				<div class="tooltip-frame-focus-glow" />
			</Show>
			<Show when={ctx?.showFiligrees()}>
				<div
					class="absolute top-1 left-1 rotate-180 size-4 bg-contain opacity-30"
					style={{ "background-image": "url(blp:mp_player_detail)" }}
				/>
				<div
					class="absolute top-1 right-1 -rotate-90 size-4 bg-contain opacity-30"
					style={{ "background-image": "url(blp:mp_player_detail)" }}
				/>
				<div
					class="absolute bottom-1 left-1 rotate-90 size-4 bg-contain opacity-30"
					style={{ "background-image": "url(blp:mp_player_detail)" }}
				/>
				<div
					class="absolute bottom-1 right-1 size-4 bg-contain opacity-30"
					style={{ "background-image": "url(blp:mp_player_detail)" }}
				/>
			</Show>
			<div
				ref={setContentRef}
				class="flex flex-col items-stretch"
			>
				{local.children}
			</div>

			<Show when={!local.hideHint}>
				<Tooltip.InspectHint
					class="relative mt-2"
					progressBarRef={setProgressBarRef}
					isLargeContent={isLargeContent}
				/>
			</Show>
		</div>
	);
};

export type TooltipTextProps = TooltipBaseProps &
	LocaleProps & {
		class?: string;
		header?: string;
		headerClass?: string;
		bodyClass?: string;
		/* False by default on text */
		showFiligrees?: boolean;
	};

interface TooltipTextInnerProps {
	text: string;
	args?: LocalizedTextArgument[];
	header?: string;
	class?: string;
	headerClass?: string;
	bodyClass?: string;
}

// Helper component to safely consume TooltipContext within provider; needed to determine if the ticket border should be used for small text tooltips.
const TooltipTextInnerComponent = (props: TooltipTextInnerProps) => {
	const ctx = useContext(TooltipContext); // Pull the context created by the parent <Tooltip> to check for nested keywords
	const hasTooltips = createMemo(() => (ctx?.childTooltipList().length ?? 0) > 0);
	const showBg = createMemo(() => !!props.header || hasTooltips());

	return (
		<Tooltip.Frame class={`relative flex flex-col pb-1 max-w-128 w-full ${props.class ?? ""}`}>
			<Show when={props.header}>
				{(header) => (
					<div
						class={`relative text-center font-title text-sm text-secondary mb-2 uppercase tracking-100 ${props.headerClass ?? ""}}`}
						role="heading"
					>
						<L10n.Compose text={header()} />
					</div>
				)}
			</Show>

			<div
				class={`flex-auto w-full ${showBg() ? "p-3" : "p-0"} ${props.bodyClass ?? ""}`}
				classList={{ "img-base-ticket-bg": showBg() }}
			>
				<L10n.Stylize
					text={props.text}
					args={props.args}
					class="relative"
				/>
			</div>
		</Tooltip.Frame>
	);
};

const TooltipTextComponent: ParentComponent<TooltipTextProps> = (props) => {
	const [local, other] = splitProps(props, [
		"text",
		"args",
		"children",
		"header",
		"class",
		"headerClass",
		"bodyClass",
	]);

	return (
		<Tooltip
			{...other}
			showFiligrees={props.showFiligrees ?? false}
		>
			<Tooltip.Trigger>{local.children}</Tooltip.Trigger>
			<Tooltip.Content>
				<TooltipTextInnerComponent {...local} />
			</Tooltip.Content>
		</Tooltip>
	);
};

const TooltipLegacyTextComponent: ParentComponent<LocaleProps> = (props) => {
	const [local, other] = splitProps(props, ["text", "args", "children"]);
	return (
		<Tooltip
			{...other}
			showFiligrees={false}
		>
			<Tooltip.Trigger>{local.children}</Tooltip.Trigger>
			<Tooltip.Content>
				<Tooltip.Frame
					class="relative flex flex-col pb-1 max-w-96 p-3 pointer-events-none break-words font-body text-xs"
					hideHint={true}
				>
					<L10n.Stylize
						text={local.text}
						args={local.args}
						class="relative"
					/>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

export type TooltipComponents = ParentComponent<TooltipBaseProps> & {
	/**
	 * The tooltips trigger component.
	 * Can be used to trigger the tooltip with the same name to be displayed.
	 * By default, tooltips have no frame, use {@link Tooltip.Frame} to add a basic frame.
	 * ```tsx
	 * <Tooltip>
	 *   <Tooltip.Trigger>
	 *   <Button>Hover Me</Button>
	 *   </Tooltip.Trigger>
	 *   <Tooltip.Content>I am a tooltip</Tooltip.Content>
	 * </Tooltip>
	 * ```
	 * @param {TriggerProps} props See {@link TriggerProps} for a full list of properties
	 */
	Trigger: ParentComponent<JSX.HTMLAttributes<HTMLDivElement>>;

	/**
	 * The tooltip content component.
	 * Renders the tooltip body in a portal and handles positioning relative to the trigger.
	 * ```tsx
	 * <Tooltip>
	 *   <Tooltip.Trigger>Hover me</Tooltip.Trigger>
	 *   <Tooltip.Content>Hi!</Tooltip.Content>
	 * </Tooltip>
	 * ```
	 */
	Content: ParentComponent<TooltipContentProps>;
	/**
	 * A text tooltip.
	 * Can be used to display a text tooltip on an activatable or derivative.
	 * ```tsx
	 * <Tooltip.Text text="I am a text tooltip">
	 *   <Activatable> Hover Me </Activatable>
	 * </Tooltip.Text>
	 * ```
	 * Default implementation: {@link TooltipTextComponent}
	 * @param {TooltipTextProps} props See {@link TooltipTextProps} for a full list of properties
	 *
	 * Commonly Used Properties:
	 * @param {string} props.text The text to display on the tooltip.
	 */
	Text: ParentComponent<TooltipTextProps>;
	/**
	 * A text tooltip formatted to look like legacy tooltips (i.e. frame only, just text).
	 * Can be used to display a text tooltip on an activatable or derivative.
	 * ```tsx
	 * <Tooltip.LegacyText text="I am a text tooltip">
	 *   <Activatable> Hover Me </Activatable>
	 * </Tooltip.LegacyText>
	 * ```
	 * Default implementation: {@link TooltipLegacyTextComponent}
	 * @param {LocaleProps} props See {@link LocaleProps} for a full list of properties
	 */
	LegacyText: ParentComponent<LocaleProps>;
	/**
	 * A basic tooltip frame.
	 * Can be used to add a basic frame around a tooltip
	 *
	 * ```tsx
	 * <Tooltip>
	 *   <Tooltip.Trigger><Button>Hover Me</Button></Tooltip.Trigger>
	 *   <Tooltip.Content>
	 *     <Tooltip.Frame>I was framed!</Tooltip.Frame>
	 *   </Tooltip.Content>
	 * </Tooltip>
	 * ```
	 * Default implementation: {@link TooltipFrameComponent}
	 */
	Frame: ParentComponent<TooltipFrameProps>;

	/**
	 * A hint to show when the tooltip can be inspected to reveal other nested tooltips.
	 *
	 * Typically included at the bottom of the tooltip after the content.
	 *
	 * ```tsx
	 * <Tooltip>
	 *   <Tooltip.Trigger><Button>Hover Me</Button></Tooltip.Trigger>
	 *   <Tooltip.Content>
	 *     <Tooltip.Frame>I was framed!</Tooltip.Frame>
	 *     <Tooltip.InspectHint />
	 *   </Tooltip.Content>
	 * </Tooltip>
	 * ```
	 *
	 * Default implementation: {@link TooltipInspectHintComponent}
	 */
	InspectHint: ParentComponent<TooltipInspectHintProps>;
};

/**
 * A custom tooltip component.
 * Can be used to display any information as a tooltip, relative to a trigger component.
 * ```tsx
 * <Tooltip>
 *   <Tooltip.Trigger><Button>Hover Me</Button></Tooltip.Trigger>
 *   <Tooltip.Content>I am a tooltip</Tooltip.Content>
 * </Tooltip>
 * ```
 * Default implementation: {@link TooltipRootComponent}
 * @param {TooltipBaseProps} props See {@link TooltipBaseProps} for a full list of properties
 */
export const Tooltip = ComponentRegistry.register(
	"Tooltip",
	TooltipRootComponent,
) as ParentComponent<TooltipBaseProps> as TooltipComponents;
Tooltip.Trigger = ComponentRegistry.register("Tooltip.Trigger", TooltipTriggerComponent);
Tooltip.Content = ComponentRegistry.register("Tooltip.Content", TooltipContentComponent);
Tooltip.Frame = ComponentRegistry.register("Tooltip.Frame", TooltipFrameComponent);
Tooltip.Text = ComponentRegistry.register("Tooltip.Text", TooltipTextComponent);
Tooltip.LegacyText = ComponentRegistry.register("Tooltip.LegacyText", TooltipLegacyTextComponent);
Tooltip.InspectHint = ComponentRegistry.register("Tooltip.InspectHint", TooltipInspectHintComponent);
